import { useState } from 'preact/hooks';

// Static reports generated by my Pitch Sequencing tool (~/Pitch Sequencing) from my own Rapsodo session.
const BASE = '/embeds/pitch-sequencing';
const reports = [
  { file: 'sequence_report.html', label: 'Sequence report', blurb: 'Best pitch and sequence for every count, from value iteration over (balls, strikes, previous pitch).' },
  { file: 'pitch_3d.html', label: '3D pitch shapes', blurb: 'Modeled flight paths, tunnel window, spin axes and batter’s-view panels.' },
  { file: 'tunnel_matrix.html', label: 'Tunnel matrix', blurb: 'How well each pitch pair tunnels: plate separation vs. tunnel-window separation.' },
  { file: 'pitch_explorer.html', label: 'Pitch explorer', blurb: 'Every pitch from the session, interactive.' },
];

export default function Baseball() {
  const [i, setI] = useState(0);
  const r = reports[i];
  return (
    <div class="embed-pane">
      <div class="embed-head">
        <div>
          <h2 class="pane-title">Pitch Sequencing</h2>
          <p class="muted small">My own Rapsodo session, analyzed with a Python tool I built. {r.blurb}</p>
        </div>
        <div class="seg" role="tablist" aria-label="Reports">
          {reports.map((x, j) => (
            <button role="tab" aria-selected={i === j} class={i === j ? 'on' : ''} onClick={() => setI(j)}>{x.label}</button>
          ))}
        </div>
      </div>
      <iframe
        key={r.file}
        class="embed-frame"
        src={`${BASE}/${r.file}`}
        title={r.label}
        loading="lazy"
        sandbox="allow-scripts allow-popups"
      />
      <p class="muted small embed-foot">
        <a href={`${BASE}/${r.file}`} target="_blank" rel="noopener">Open full screen ↗</a>
      </p>
    </div>
  );
}
